(function () {
	'use strict';

	var STORAGE_KEY = 'todos-javascript-app';
	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var todos = [];
	var editingId = null;
	var currentFilter = '/';

	// --- Persistence ---

	function save() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function load() {
		try {
			var raw = localStorage.getItem(STORAGE_KEY);
			if (raw) todos = JSON.parse(raw);
		} catch (e) {
			todos = [];
		}
	}

	// --- Model ---

	function generateId() {
		return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
	}

	function addTodo(title) {
		var trimmed = title.trim();
		if (!trimmed) return;
		todos.push({ id: generateId(), title: trimmed, completed: false });
		save();
	}

	function toggleTodo(id) {
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id === id) {
				todos[i].completed = !todos[i].completed;
				break;
			}
		}
		save();
	}

	function toggleAll() {
		var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
		todos.forEach(function (t) { t.completed = !allCompleted; });
		save();
	}

	function editTodo(id, newTitle) {
		var trimmed = newTitle.trim();
		if (!trimmed) {
			todos = todos.filter(function (t) { return t.id !== id; });
		} else {
			for (var i = 0; i < todos.length; i++) {
				if (todos[i].id === id) {
					todos[i].title = trimmed;
					break;
				}
			}
		}
		editingId = null;
		save();
	}

	function cancelEdit() {
		editingId = null;
	}

	function destroyTodo(id) {
		todos = todos.filter(function (t) { return t.id !== id; });
		save();
	}

	function clearCompleted() {
		todos = todos.filter(function (t) { return !t.completed; });
		save();
	}

	function getFilteredTodos() {
		switch (currentFilter) {
			case '/active':
				return todos.filter(function (t) { return !t.completed; });
			case '/completed':
				return todos.filter(function (t) { return t.completed; });
			default:
				return todos.slice();
		}
	}

	// --- Rendering ---

	function pluralize(count) {
		return count === 1 ? 'item' : 'items';
	}

	function render() {
		var filtered = getFilteredTodos();
		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		var completedCount = todos.filter(function (t) { return t.completed; }).length;
		var hasTodos = todos.length > 0;

		// Main section and footer visibility
		var mainSection = document.querySelector('.main');
		var footer = document.querySelector('.todoapp > .footer');
		mainSection.style.display = hasTodos ? '' : 'none';
		footer.style.display = hasTodos ? '' : 'none';

		// Toggle all checkbox
		var toggleAll = document.getElementById('toggle-all');
		toggleAll.checked = hasTodos && activeCount === 0;

		// Todo list
		var list = document.querySelector('.todo-list');
		list.innerHTML = '';

		filtered.forEach(function (todo) {
			var li = document.createElement('li');
			li.setAttribute('data-id', todo.id);
			if (todo.completed) li.classList.add('completed');
			if (editingId === todo.id) li.classList.add('editing');

			var viewDiv = document.createElement('div');
			viewDiv.className = 'view';

			var checkbox = document.createElement('input');
			checkbox.className = 'toggle';
			checkbox.type = 'checkbox';
			if (todo.completed) checkbox.checked = true;

			var label = document.createElement('label');
			label.textContent = todo.title;

			var destroyBtn = document.createElement('button');
			destroyBtn.className = 'destroy';

			viewDiv.appendChild(checkbox);
			viewDiv.appendChild(label);
			viewDiv.appendChild(destroyBtn);

			var editInput = document.createElement('input');
			editInput.className = 'edit';
			editInput.value = todo.title;

			li.appendChild(viewDiv);
			li.appendChild(editInput);
			list.appendChild(li);
		});

		// Counter
		var countEl = document.querySelector('.todo-count');
		countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralize(activeCount) + ' left';

		// Clear completed button
		var clearBtn = document.querySelector('.clear-completed');
		clearBtn.style.display = completedCount > 0 ? '' : 'none';

		// Filter links
		var filterLinks = document.querySelectorAll('.filters a');
		filterLinks.forEach(function (link) {
			link.classList.remove('selected');
			var href = link.getAttribute('href');
			if (href === '#/' + currentFilter || (href === '#/' && currentFilter === '/')) {
				link.classList.add('selected');
			}
		});
	}

	// --- Event Handlers ---

	function setupEventListeners() {
		var newTodoInput = document.querySelector('.new-todo');
		var toggleAll = document.getElementById('toggle-all');
		var list = document.querySelector('.todo-list');
		var clearBtn = document.querySelector('.clear-completed');

		// New todo input
		newTodoInput.addEventListener('keydown', function (e) {
			if (e.keyCode === ENTER_KEY) {
				addTodo(newTodoInput.value);
				newTodoInput.value = '';
				render();
			}
		});

		// Toggle all
		toggleAll.addEventListener('change', function () {
			toggleAll();
			render();
		});

		// Delegate events on the todo list
		list.addEventListener('click', function (e) {
			var target = e.target;
			var li = target.closest('li');
			if (!li) return;
			var id = li.getAttribute('data-id');

			if (target.classList.contains('toggle')) {
				toggleTodo(id);
				render();
			} else if (target.classList.contains('destroy')) {
				destroyTodo(id);
				render();
			}
		});

		list.addEventListener('dblclick', function (e) {
			var target = e.target;
			if (target.tagName !== 'LABEL') return;
			var li = target.closest('li');
			if (!li) return;
			var id = li.getAttribute('data-id');
			editingId = id;
			render();
			var editInput = li.querySelector('.edit');
			if (editInput) editInput.focus();
		});

		list.addEventListener('blur', function (e) {
			if (e.target.classList.contains('edit')) {
				var li = e.target.closest('li');
				if (!li) return;
				var id = li.getAttribute('data-id');
				editTodo(id, e.target.value);
				render();
			}
		}, true);

		list.addEventListener('keydown', function (e) {
			if (e.target.classList.contains('edit')) {
				var li = e.target.closest('li');
				if (!li) return;
				var id = li.getAttribute('data-id');
				if (e.keyCode === ENTER_KEY) {
					editTodo(id, e.target.value);
					render();
				} else if (e.keyCode === ESCAPE_KEY) {
					cancelEdit();
					render();
				}
			}
		});

		// Clear completed
		clearBtn.addEventListener('click', function () {
			clearCompleted();
			render();
		});

		// Routing
		window.addEventListener('hashchange', function () {
			var hash = window.location.hash || '#/';
			currentFilter = hash.replace('#', '') || '/';
			render();
		});
	}

	// --- Init ---

	function init() {
		load();
		setupEventListeners();
		var hash = window.location.hash || '#/';
		currentFilter = hash.replace('#', '') || '/';
		render();
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}
})();

